<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigInvitationExpiryDaysAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigInvitationExpiryDaysAccessor trait.
 *
 * Covers null default, string/VO assignment via withInvitationExpiryDays,
 * getInvitationExpiryDays/invitationExpiryDays accessors, and isInvitationExpiryDaysChanged with/without original.
 */
class TenantConfigInvitationExpiryDaysAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withInvitationExpiryDays creates a new instance with the InvitationExpiryDays set
     * from a string value, and getInvitationExpiryDays returns the primitive string.
     */
    public function testWithInvitationExpiryDaysFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigInvitationExpiryDaysAccessorUnitTest();

        // Act
        $result = $holder->withInvitationExpiryDays(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->getInvitationExpiryDays());
    }
    /**
     * Asserts that withinvitationExpiryDays has access to the value object
     * from a string value, and getInvitationExpiryDays returns the primitive string.
     */
    public function testWithInvitationExpiryDaysFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigInvitationExpiryDaysAccessorUnitTest();

        // Act
        $result = $holder->withInvitationExpiryDays(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->invitationExpiryDays()->value());
    }
    public function testChangedInvitationExpiryDays(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigInvitationExpiryDaysAccessorUnitTest()->withInvitationExpiryDays(1);
        $original = $holder->withInvitationExpiryDays(1);
        $same = $holder->withInvitationExpiryDays(1);
        $modified = $holder->withInvitationExpiryDays(2);

        // Act
        $withSame = $original->isInvitationExpiryDaysChanged($same);
        $withDiferent = $original->isInvitationExpiryDaysChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigInvitationExpiryDaysAccessorUnitTest
{
    use TenantConfigInvitationExpiryDaysAccessor;
}
